import fs from 'node:fs';import assert from 'node:assert/strict';import http from 'node:http';import {hash,json} from './bounded-source-hash-20261026.mjs';
const dir='F:/VisibleMedicine/staging/20261026-workbook-history-browser',source='F:/VisibleMedicine/staging/20261026-review-count-website/SOURCE_CANDIDATE.json',parent=json(source);
assert(process.stdin.isTTY);assert.deepEqual(json('CURRENT_CHECKPOINT.json').activeWork.current.activeExecutionSessions,[]);assert.equal(json('CURRENT_CHECKPOINT.json').activeWork.current.ownerPreviewPolicy.restartPermitted,false);
const html=v=>`<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Synthetic workbook history QA</title><style>body{margin:20px;font:16px system-ui;color:#143c43;background:#f7faf8}button,input,select,textarea{font:inherit;margin:6px;padding:8px}input[type=text],input:not([type]),textarea{min-width:260px}label{display:block}a{color:#135775}.qa-notice{background:#e7f1ec;padding:12px}[hidden]{display:none!important}.content-editor-toolbar{display:flex;align-items:center;gap:12px}.management-card{padding:12px;border:1px solid #cddbd4}fieldset{border:0}.content-editor-steps{display:flex}</style><div id="root"></div><script src="/${v}.js"></script></html>`;
const server=http.createServer((req,res)=>{res.setHeader('Cache-Control','no-store');res.setHeader('X-Content-Type-Options','nosniff');res.setHeader('Content-Security-Policy',"default-src 'none';script-src 'self';style-src 'unsafe-inline';connect-src 'none';base-uri 'none';frame-ancestors 'none';form-action 'none'");if(req.method!=='GET'){res.writeHead(405).end();return;}const pathname=new URL(req.url,'http://127.0.0.1').pathname,match=pathname.match(/^\/(baseline|candidate)\/(?:course|builder)$/);if(match){res.writeHead(200,{'Content-Type':'text/html'}).end(html(match[1]));return;}if(/^\/(baseline|candidate)\.js$/.test(pathname)&&fs.existsSync(dir+pathname)){res.writeHead(200,{'Content-Type':'text/javascript'}).end(fs.readFileSync(dir+pathname));return;}res.writeHead(404).end();});
await new Promise(resolve=>server.listen(0,'127.0.0.1',resolve));const address=server.address(),url='http://127.0.0.1:'+address.port;assert.notEqual(address.port,3000);
const live=active=>{const ix=json('CURRENT_CHECKPOINT.json');ix.activeWork.current.activeExecutionSessions=ix.activeWork.current.activeExecutionSessions.filter(r=>r.role!=='workbook-history-synthetic-qa');if(active)ix.activeWork.current.activeExecutionSessions.push({role:'workbook-history-synthetic-qa',pid:process.pid,url,evidence:dir,syntheticOnly:true,normalPreviewChanged:false});fs.writeFileSync('CURRENT_CHECKPOINT.json',JSON.stringify(ix,null,2)+'\n');};
const response=await fetch(url+'/baseline/course');assert.equal(response.status,200);await response.arrayBuffer();live(true);
fs.writeFileSync(dir+'/STARTED.json',JSON.stringify({at:new Date().toISOString(),pid:process.pid,url,ready:200,controllerSha256:hash(new URL(import.meta.url)),syntheticOnly:true,normalPreviewChanged:false},null,2)+'\n',{flag:'wx'});console.log(JSON.stringify({pid:process.pid,url}));
process.stdin.setEncoding('utf8');await new Promise(resolve=>{process.stdin.on('data',s=>{if(s.includes('q'))resolve();});process.stdin.once('end',resolve);process.once('SIGINT',resolve)});process.stdin.pause();server.closeAllConnections();await new Promise(resolve=>server.close(resolve));
const drift=parent.sourceRows.filter(r=>hash(parent.website+'/'+r.path)!==r.sha256).map(r=>r.path);assert.deepEqual(drift,[]);live(false);fs.writeFileSync(dir+'/TERMINAL.json',JSON.stringify({at:new Date().toISOString(),pid:process.pid,sourceDrift:drift,graceful:true,normalPreviewChanged:false},null,2)+'\n',{flag:'wx'});console.log(JSON.stringify({stopped:true,sourceDrift:0}));
